questionvariables.text:
nval : rand([2,3]);
kval : rand([2,3,5]);
x1 : 2; x2 : 3; x3 : 4;
y1 : kval*x1^nval;
y2 : kval*x2^nval;
y3 : kval*x3^nval;
px1 : log(x1)/log(10);   /* log10 x */
px2 : log(x2)/log(10);
px3 : log(x3)/log(10);
py1 : log(y1)/log(10);   /* log10 y */
py2 : log(y2)/log(10);
py3 : log(y3)/log(10);
cval : log(kval)/log(10);   /* intercept = log10 k */
/* graph window */
gxlo : -0.1;
gxhi : px3 + 0.15;
gylo : min(0, cval, py1) - 0.1;
gyhi : max(py1, py2, py3) + 0.2;
